ALTER TABLE "workforce_records" ADD CONSTRAINT "workforce_records_description_check" CHECK (length(btrim("workforce_records"."description")) BETWEEN 1 AND 1000);--> statement-breakpoint
ALTER TABLE "workforce_records" ADD CONSTRAINT "workforce_records_kind_fields_check" CHECK (("workforce_records"."kind" = 'EARNING' AND "workforce_records"."engagement_type" IS NOT NULL AND (("workforce_records"."engagement_type" IN ('DAILY','HOURLY','QUANTITY') AND "workforce_records"."quantity" IS NOT NULL AND "workforce_records"."rate_toman" IS NOT NULL) OR ("workforce_records"."engagement_type" IN ('MONTHLY','FIXED_CONTRACT','MANUAL') AND "workforce_records"."quantity" IS NULL AND "workforce_records"."rate_toman" IS NULL))) OR ("workforce_records"."kind" <> 'EARNING' AND "workforce_records"."engagement_type" IS NULL AND "workforce_records"."quantity" IS NULL AND "workforce_records"."rate_toman" IS NULL));--> statement-breakpoint
ALTER TABLE "workforce_records" ADD CONSTRAINT "workforce_records_payment_kind_check" CHECK (("workforce_records"."kind" = 'WORKER_PAYMENT' AND "workforce_records"."payment_kind" IN ('PAYMENT','ADVANCE')) OR ("workforce_records"."kind" <> 'WORKER_PAYMENT' AND "workforce_records"."payment_kind" IS NULL));--> statement-breakpoint
ALTER TABLE "workforce_records" ADD CONSTRAINT "workforce_records_finalized_fields_check" CHECK (("workforce_records"."status" = 'DRAFT' AND "workforce_records"."finalized_by" IS NULL AND "workforce_records"."finalized_at" IS NULL) OR ("workforce_records"."status" IN ('FINALIZED','REVERSED') AND "workforce_records"."finalized_by" IS NOT NULL AND "workforce_records"."finalized_at" IS NOT NULL));